import 'package:flutter/material.dart';

class LoadingStateView extends StatelessWidget { const LoadingStateView({super.key}); @override Widget build(BuildContext context) => const Center(child: CircularProgressIndicator()); }
class ErrorStateView extends StatelessWidget { const ErrorStateView({required this.message, required this.onRetry, super.key}); final String message; final VoidCallback onRetry; @override Widget build(BuildContext context) => Center(child: Padding(padding: const EdgeInsets.all(24), child: Column(mainAxisSize: MainAxisSize.min, children: [Icon(Icons.wifi_off_outlined, size: 40, color: Theme.of(context).colorScheme.error), const SizedBox(height: 12), Text(message, textAlign: TextAlign.center), const SizedBox(height: 16), OutlinedButton.icon(onPressed: onRetry, icon: const Icon(Icons.refresh), label: const Text('Retry'))]))); }
class EmptyStateView extends StatelessWidget { const EmptyStateView({required this.title, required this.message, this.icon = Icons.search_off, super.key}); final String title; final String message; final IconData icon; @override Widget build(BuildContext context) => Center(child: Padding(padding: const EdgeInsets.all(24), child: Column(mainAxisSize: MainAxisSize.min, children: [Icon(icon, size: 44, color: Theme.of(context).colorScheme.primary), const SizedBox(height: 12), Text(title, style: Theme.of(context).textTheme.titleMedium, textAlign: TextAlign.center), const SizedBox(height: 6), Text(message, textAlign: TextAlign.center)]))); }